async def list_directory(request: Request):
    body = await request.json()
    raw_path = body.get("path")
    base = Path.home()

    if raw_path:
        target = Path(raw_path).resolve()
        if not str(target).startswith(str(base)):
            return JSONResponse(status_code=403, content={"detail": "Access denied"})
    else:
        target = base

    if not target.is_dir():
        return JSONResponse(status_code=404, content={"detail": "Not a directory"})

    raw_limit = body.get("limit")
    raw_cursor = body.get("cursor")
    paginate = raw_limit is not None or raw_cursor is not None

    if paginate:
        try:
            limit = int(raw_limit) if raw_limit is not None else _DEFAULT_PAGE_LIMIT
        except (TypeError, ValueError):
            return JSONResponse(status_code=400, content={"detail": "limit must be an integer"})
        limit = max(1, min(limit, _MAX_PAGE_LIMIT))
        offset = _decode_cursor(raw_cursor) if raw_cursor else 0
    else:
        limit = None
        offset = 0

    all_entries = []
    try:
        for entry in sorted(target.iterdir(), key=lambda e: (not e.is_dir(), e.name.lower())):
            all_entries.append(entry)
    except PermissionError:
        pass

    if paginate:
        page = all_entries[offset : offset + limit]
        next_offset = offset + limit
        next_cursor = _encode_cursor(next_offset) if next_offset < len(all_entries) else None
    else:
        page = all_entries
        next_cursor = None

    dirs = []
    files = []
    for entry in page:
        if entry.is_dir():
            dirs.append({"name": entry.name, "path": str(entry)})
        else:
            files.append({"name": entry.name, "path": str(entry)})

    parent = str(target.parent) if target != base else None

    return {
        "path": str(target),
        "parent": parent,
        "dirs": dirs,
        "files": files,
        "next_cursor": next_cursor,
    }
